// Package specgen generates per-target specifications, harness bindings and
// the runtime library reference from the canonical contract catalog.
package specgen

import (
	"bytes"
	"fmt"
	"io/fs"
	"path"
	"sort"
	"strings"

	"github.com/eugenioenko/goalchemy/internal/contracts"
	"github.com/eugenioenko/goalchemy/internal/link"
)

const Marker = "Code generated by goalchemy spec generate. DO NOT EDIT."

// Files maps repository-relative paths to generated content.
type Files map[string][]byte

// Generate produces every generated file for every target in the catalog,
// plus the runtime library reference.
func Generate(cat *contracts.Catalog) (Files, error) {
	out := Files{}
	names := make([]string, 0, len(cat.Targets))
	for n := range cat.Targets {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		t := cat.Targets[n]
		if err := targetSpecs(cat, t, out); err != nil {
			return nil, err
		}
		if t.Harness != nil {
			gen, ok := harnessGenerators[n]
			if !ok {
				return nil, fmt.Errorf("no harness generator for target %s", n)
			}
			src, err := gen(cat, t)
			if err != nil {
				return nil, fmt.Errorf("%s harness: %w", n, err)
			}
			out[path.Join(t.Dir, t.Harness.Generated)] = src
		}
	}
	lib, err := libraryDoc(cat)
	if err != nil {
		return nil, fmt.Errorf("library reference: %w", err)
	}
	out[LibraryDoc] = lib
	return out, nil
}

var harnessGenerators = map[string]func(*contracts.Catalog, *contracts.Target) ([]byte, error){}

func quote(s string) string { return fmt.Sprintf("%q", s) }

func targetSpecs(cat *contracts.Catalog, t *contracts.Target, out Files) error {
	for _, impl := range t.Functions {
		fc, ok := cat.Functions[impl.ID]
		if !ok {
			return fmt.Errorf("%s: unknown contract %s", t.Target, impl.ID)
		}
		src, err := fs.ReadFile(cat.FS, path.Join(t.Dir, impl.Implementation))
		if err != nil {
			return err
		}
		var b bytes.Buffer
		fmt.Fprintf(&b, "# %s\ntarget: %s\nfunction: %s\ncontract_version: %s\ncontract_hash: %s\n",
			Marker, t.Target, fc.ID, fc.Version, fc.Hash)
		fmt.Fprintf(&b, "symbol: %s\nimplementation: %s\nimplementation_hash: %s\n", quote(impl.Symbol), impl.Implementation, link.Hash(src))
		fmt.Fprintf(&b, "summary: %s\nsuspension: %s\ndeterminism: %s\n", quote(fc.Summary), fc.Suspension, fc.Determinism)
		b.WriteString("signature:\n  type_parameters:")
		if len(fc.Signature.TypeParameters) == 0 {
			b.WriteString(" []\n")
		} else {
			b.WriteString("\n")
			for _, tp := range fc.Signature.TypeParameters {
				fmt.Fprintf(&b, "    - {name: %s, family: %s}\n", tp.Name, tp.Family)
			}
		}
		for _, group := range []struct {
			name string
			ps   []contracts.Param
		}{{"inputs", fc.Signature.Inputs}, {"outputs", fc.Signature.Outputs}} {
			fmt.Fprintf(&b, "  %s:", group.name)
			if len(group.ps) == 0 {
				b.WriteString(" []\n")
				continue
			}
			b.WriteString("\n")
			for _, p := range group.ps {
				fmt.Fprintf(&b, "    - {name: %s, type: %s}\n", p.Name, quote(p.Type))
			}
		}
		inst := map[string]bool{}
		var insts []string
		for _, c := range fc.Cases {
			keys := make([]string, 0, len(c.Types))
			for k := range c.Types {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			var parts []string
			for _, k := range keys {
				parts = append(parts, k+": "+quote(c.Types[k]))
			}
			s := "{" + strings.Join(parts, ", ") + "}"
			if !inst[s] {
				inst[s] = true
				insts = append(insts, s)
			}
		}
		b.WriteString("tested_instantiations:")
		if len(insts) == 0 {
			b.WriteString(" []\n")
		} else {
			b.WriteString("\n")
			for _, s := range insts {
				fmt.Fprintf(&b, "  - %s\n", s)
			}
		}
		if len(impl.Requires) > 0 {
			fmt.Fprintf(&b, "requires: [%s]\n", strings.Join(impl.Requires, ", "))
		}
		var cases []string
		for _, c := range fc.Cases {
			cases = append(cases, c.Name)
		}
		fmt.Fprintf(&b, "cases: [%s]\n", strings.Join(cases, ", "))
		specPath := path.Join(t.Dir, "spec", strings.TrimSuffix(strings.TrimPrefix(impl.Implementation, "runtime/"), path.Ext(impl.Implementation))+".yaml")
		out[specPath] = b.Bytes()
	}
	return nil
}

// Check compares generated files with the catalog filesystem and reports
// missing, stale, or hand-edited files, plus stray files in spec directories.
func Check(cat *contracts.Catalog, files Files) []string {
	var problems []string
	paths := make([]string, 0, len(files))
	for p := range files {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		have, err := fs.ReadFile(cat.FS, p)
		switch {
		case err != nil:
			problems = append(problems, p+": missing generated file")
		case !bytes.Equal(have, files[p]):
			problems = append(problems, p+": stale or hand-edited generated file")
		}
	}
	for _, t := range cat.Targets {
		_ = fs.WalkDir(cat.FS, path.Join(t.Dir, "spec"), func(p string, d fs.DirEntry, err error) error {
			if err == nil && !d.IsDir() {
				if _, ok := files[p]; !ok {
					problems = append(problems, p+": generated spec has no runtime implementation")
				}
			}
			return nil
		})
	}
	return problems
}
